  "schedule-create": {"type":"schedule-create","behavior":"schedule","area":"config","title":"Schedule","method":"create","label":"Create","description":"Deploy a cron entry","httpMethod":"POST","path":"/api/node/{hostname}/schedule","permission":"schedule:write","write":true,"fields":[{"name":"name","in":"body","kind":"string","required":true,"doc":"The entry, and its file name, such as backup"},{"name":"object","in":"body","kind":"string","required":true,"doc":"The object that holds the entry, from osapi client file upload"},{"name":"schedule","in":"body","kind":"string","required":false,"doc":"A cron expression, such as */5 * * * *; give it or interval"},{"name":"interval","in":"body","kind":"string","required":false,"doc":"The interval of a script in /etc/cron.daily and the like; give it or schedule","options":["hourly","daily","weekly","monthly"]},{"name":"user","in":"body","kind":"string","required":false,"doc":"The user the entry runs as"},{"name":"content_type","in":"body","kind":"string","required":false,"doc":"The content type: raw, or template to render the object with the agent's facts and vars; the object's own when empty","options":["raw","template"]},{"name":"vars","in":"body","kind":"object","required":false,"doc":"The vars of a template, as key=value"}],"columns":[{"name":"name","label":"Name","doc":"The entry","kind":"value"},{"name":"changed","label":"Changed","doc":"Whether the host changed","kind":"value"}]},
